import * as THREE from 'three';
import {makePlane} from './vehicles.js';
import {destinations,getDestination,announceDestination} from './destinations.js';
import {journeyAudio} from './soundscape.js';

const $=selector=>document.querySelector(selector);
const clamp=THREE.MathUtils.clamp;
const prefersReducedMotion=()=>window.zrMotionPaused||matchMedia('(prefers-reduced-motion: reduce)').matches;
const earthTexture=new THREE.TextureLoader().load('./assets/earth-atmosphere.jpg');
earthTexture.colorSpace=THREE.SRGBColorSpace;
const geo=(lat,lon,r)=>{const p=(90-lat)*Math.PI/180,t=(lon+180)*Math.PI/180;return new THREE.Vector3(-r*Math.sin(p)*Math.cos(t),r*Math.cos(p),r*Math.sin(p)*Math.sin(t));};

function tidalWater(radius){
 return new THREE.Mesh(new THREE.SphereGeometry(radius,innerWidth<760?72:112,innerWidth<760?48:72),new THREE.ShaderMaterial({
  uniforms:{time:{value:0},earthMap:{value:earthTexture}},transparent:true,depthWrite:false,
  vertexShader:`uniform float time;varying vec2 uvMap;varying vec3 surface;varying vec3 normalView;varying float crest;void main(){vec3 n=normalize(position),moon=normalize(vec3(.25*sin(time*.18),1.,.18*cos(time*.18)));float a=dot(n,moon),bulge=.12*pow(max(a,0.),12.)+.035*pow(max(-a,0.),8.);float ripples=sin(n.x*35.+time*1.5+sin(n.z*19.-time))*.008+sin(n.y*53.-time*1.6+n.z*23.)*.005;vec3 p=n*(length(position)+bulge+ripples);uvMap=uv;crest=bulge;surface=(modelViewMatrix*vec4(p,1.)).xyz;normalView=normalize(normalMatrix*n);gl_Position=projectionMatrix*vec4(surface,1.);}`,
  fragmentShader:`uniform sampler2D earthMap;uniform float time;varying vec2 uvMap;varying vec3 surface;varying vec3 normalView;varying float crest;void main(){vec3 map=texture2D(earthMap,uvMap).rgb;float ocean=smoothstep(-.02,.12,map.b-map.r);vec3 v=normalize(-surface);float fres=pow(1.-max(dot(normalize(normalView),v),0.),4.);float current=.5+.5*sin(uvMap.y*160.+uvMap.x*90.+time*1.7)+.25*sin(uvMap.x*260.-time*1.2);float foam=smoothstep(.055,.12,crest)*pow(current,8.);vec3 water=mix(vec3(.005,.07,.12),vec3(.03,.42,.55),current*.52);water+=vec3(.32,.82,.86)*fres*.75;water=mix(water,vec3(.78,.9,.88),foam);gl_FragColor=vec4(water,ocean*(.18+fres*.45+foam*.55));}`
 }));
}

const pilot=$('#pilot');
pilot.innerHTML=`<canvas id="flightCanvas" tabindex="0" aria-label="Interactive 3D helicopter route. Use the controls below for an accessible alternative."></canvas>
 <div class="flight-hud"><p class="eyebrow">ZR–02 / INTERNATIONAL FLIGHT</p><h2 id="flightHeading">Choose your next chapter.</h2><p id="flightRoute" aria-live="polite">Travel between countries by aircraft.</p><button id="closeFlight">Exit flight ×</button></div>
 <div class="flight-telemetry" aria-live="polite"><span id="flightState">STANDBY</span><span id="flightSpeed">0 KM/H</span><span id="flightAltitude">0 M</span><span id="flightProgress">0%</span></div>
 <div class="flight-flight-controls"><label for="flightDestination">Destination</label><select id="flightDestination"></select><button id="takeFlight">Start flight →</button><button id="pauseFlight" aria-pressed="false" disabled>Pause</button><button id="flightCamera" aria-pressed="false">Camera: chase</button><button id="resetFlight" disabled>Restart</button><button id="skipFlight">Enter destination →</button><button data-sound-toggle>Sound off</button></div>
 <p class="flight-instructions">W/S pitch · A/D bank · Q/E throttle · C camera · Space pause · Enter destination · Escape exit</p>
 <div class="jet-touch" aria-label="Aircraft controls"><button data-jet="up" aria-label="Pitch up">↑</button><button data-jet="left" aria-label="Bank left">←</button><button data-jet="down" aria-label="Pitch down">↓</button><button data-jet="right" aria-label="Bank right">→</button><button data-jet="slower" aria-label="Reduce throttle">−</button><button data-jet="faster" aria-label="Increase throttle">+</button></div>`;
pilot.setAttribute('aria-labelledby','flightHeading');
destinations.forEach(d=>$('#flightDestination').add(new Option(`${d.city} · ${d.country}`,d.city)));
journeyAudio.bindControls();

let open=false,from='London',to='London',progress=0,flying=false,paused=false,last=performance.now(),returnFocus=null;
let renderer=null,scene,camera,aircraft,path,line,clouds,flightWater,contextLost=false;
let throttle=.62,bankInput=0,liftInput=0,bank=0,lift=0,cameraMode=0,currentOrigin='London';
const keys={left:false,right:false,up:false,down:false,faster:false,slower:false};
const cameraNames=['chase','orbit','cockpit'];

function setStatus(label){$('#flightState').textContent=label;}
function updateTelemetry(){$('#flightSpeed').textContent=`${Math.round(95+throttle*155)} KM/H`;$('#flightAltitude').textContent=`${Math.round(420+lift*260)} M`;$('#flightProgress').textContent=`${Math.round(progress*100)}%`;}
function setButtons(){$('#pauseFlight').disabled=!flying;$('#resetFlight').disabled=!path;$('#pauseFlight').textContent=paused?'Resume':'Pause';$('#pauseFlight').setAttribute('aria-pressed',String(paused));$('#flightCamera').textContent=`Camera: ${cameraNames[cameraMode]}`;$('#flightCamera').setAttribute('aria-pressed',String(cameraMode!==0));}
function setup(){
 if(renderer&&!contextLost)return;const canvas=$('#flightCanvas');renderer=new THREE.WebGLRenderer({canvas,antialias:innerWidth>760,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,innerWidth<760?1.25:1.65));renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.outputColorSpace=THREE.SRGBColorSpace;
 scene=new THREE.Scene();scene.background=new THREE.Color(0x06131e);scene.fog=new THREE.FogExp2(0x06131e,.012);camera=new THREE.PerspectiveCamera(45,1,.1,200);scene.add(new THREE.HemisphereLight(0xe6f5ff,0x345260,3));const sun=new THREE.DirectionalLight(0xffe1bd,4);sun.position.set(-15,15,12);scene.add(sun);
 earth=new THREE.Mesh(new THREE.SphereGeometry(9,innerWidth<760?64:96,innerWidth<760?48:72),new THREE.MeshStandardMaterial({map:earthTexture,roughness:.52,metalness:.08}));scene.add(earth);flightWater=tidalWater(9.11);scene.add(flightWater);aircraft=makePlane(scene,.72);
 clouds=new THREE.Group();scene.add(clouds);const cloudMat=new THREE.MeshBasicMaterial({color:0xc8e5ee,transparent:true,opacity:.045,depthWrite:false});for(let i=0;i<(innerWidth<760?12:24);i++){const c=new THREE.Mesh(new THREE.SphereGeometry(.8,8,6),cloudMat);c.position.copy(geo((i*37)%130-65,i*57%360-180,11.8));c.scale.set(2.5,.45,1);clouds.add(c);}contextLost=false;
}
function openPilot(){if(open)return;returnFocus=document.activeElement;open=true;pilot.classList.add('is-open');pilot.setAttribute('aria-hidden','false');document.body.classList.add('pilot-open');try{setup();setStatus('STANDBY');}catch{renderer=null;setStatus('2D MODE');$('#flightRoute').textContent='3D is unavailable here. Choose a destination to open its story.';}$('#closeFlight').focus();journeyAudio.mix();}
function closePilot(){open=false;flying=false;paused=false;Object.keys(keys).forEach(k=>keys[k]=false);journeyAudio.setVehicle('flight',{active:false});pilot.classList.remove('is-open');pilot.setAttribute('aria-hidden','true');document.body.classList.remove('pilot-open');setButtons();returnFocus?.focus({preventScroll:true});journeyAudio.mix();}
function arrive(){const destination=to;from=destination;closePilot();window.zrOpenCity?.(destination);window.zrSelectDestination?.(destination);announceDestination(destination);journeyAudio.play('city-arrival',.45);}
function buildPath(city,origin=from){const d=getDestination(city),start=getDestination(origin)||destinations[0];if(!d)return false;to=d.city;currentOrigin=start.city;$('#flightDestination').value=to;$('#flightHeading').textContent=d.city;$('#flightRoute').textContent=`${start.city} → ${d.city} · ${d.country}`;const a=geo(start.lat,start.lon,9.7),b=geo(d.lat,d.lon,9.7),points=[];for(let i=0;i<=72;i++){const t=i/72;let v=a.clone().lerp(b,t);if(v.length()<.1)v=a.clone();v.normalize().multiplyScalar(9.7+Math.sin(t*Math.PI)*3.5);points.push(v);}path=new THREE.CatmullRomCurve3(points);if(line){scene.remove(line);line.geometry.dispose();line.material.dispose();}line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(path.getPoints(120)),new THREE.LineBasicMaterial({color:0xf0c989,transparent:true,opacity:.7}));scene.add(line);return true;}
function fly(city,origin=from){const d=getDestination(city);if(!d)return;openPilot();if(prefersReducedMotion()||!renderer){to=d.city;$('#flightDestination').value=to;arrive();return;}if(!buildPath(d.city,origin))return;progress=0;throttle=.62;bank=lift=0;paused=false;flying=true;setStatus('EN ROUTE');setButtons();updateTelemetry();journeyAudio.play('jet-flyby',.42);$('#flightCanvas').focus({preventScroll:true});}
function resetFlight(){if(path)fly(to,currentOrigin);}function togglePause(){if(!flying)return;paused=!paused;setStatus(paused?'HOLDING':'EN ROUTE');setButtons();journeyAudio.setVehicle('flight',{active:!paused,speed:throttle*18,throttle});}function cycleCamera(){cameraMode=(cameraMode+1)%cameraNames.length;setButtons();}

window.zrFlyTo=fly;$('#launchPilot').onclick=()=>openPilot();$('#aircraftMode')?.addEventListener('click',()=>openPilot());$('#closeFlight').onclick=closePilot;$('#takeFlight').onclick=()=>fly($('#flightDestination').value);$('#skipFlight').onclick=()=>{to=$('#flightDestination').value;arrive();};$('#pauseFlight').onclick=togglePause;$('#flightCamera').onclick=cycleCamera;$('#resetFlight').onclick=resetFlight;
const keyMap={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'up',KeyW:'up',ArrowDown:'down',KeyS:'down',KeyE:'faster',KeyQ:'slower'};
addEventListener('keydown',event=>{if(!open)return;if(event.code==='Escape'){event.preventDefault();closePilot();return;}if(event.code==='Tab'){const focusable=[...pilot.querySelectorAll('button:not(:disabled),select,input,[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}return;}if(event.target.closest('select,input,button'))return;if(keyMap[event.code]){event.preventDefault();keys[keyMap[event.code]]=true;}if(event.code==='Space'){event.preventDefault();togglePause();}if(event.code==='KeyC'){event.preventDefault();cycleCamera();}if(event.code==='Enter'){event.preventDefault();if(!flying)fly($('#flightDestination').value);else if(progress>.92)arrive();else setStatus('CONTINUE ROUTE');}});
addEventListener('keyup',event=>{if(keyMap[event.code])keys[keyMap[event.code]]=false;});addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));pilot.querySelectorAll('[data-jet]').forEach(button=>{button.onpointerdown=event=>{event.preventDefault();button.setPointerCapture(event.pointerId);keys[button.dataset.jet]=true;};button.onpointerup=button.onpointercancel=()=>keys[button.dataset.jet]=false;});

function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;if(!open||!renderer||contextLost||document.hidden)return;const canvas=$('#flightCanvas'),w=canvas.clientWidth,h=canvas.clientHeight;if(w<1||h<1)return;const ratio=renderer.getPixelRatio();if(canvas.width!==Math.round(w*ratio)||canvas.height!==Math.round(h*ratio)){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}bankInput=(keys.left?1:0)-(keys.right?1:0);liftInput=(keys.up?1:0)-(keys.down?1:0);throttle=clamp(throttle+((keys.faster?1:0)-(keys.slower?1:0))*dt*.35,.25,1);bank=THREE.MathUtils.damp(bank,bankInput*.42,5,dt);lift=THREE.MathUtils.damp(lift,liftInput,4,dt);
 if(flying&&!paused&&!prefersReducedMotion()){progress=Math.min(1,progress+dt*(.105+throttle*.12));const p=path.getPoint(progress),normal=p.clone().normalize(),tangent=path.getTangent(Math.min(progress,.999));p.addScaledVector(normal,lift*.55);const side=new THREE.Vector3().crossVectors(tangent,normal).normalize();p.addScaledVector(side,bank*.3);aircraft.position.copy(p);aircraft.up.copy(normal);aircraft.lookAt(p.clone().add(tangent));aircraft.rotateY(Math.PI);aircraft.rotateZ(bank+Math.sin(progress*Math.PI*2)*.08);aircraft.rotateX(-lift*.12);const chase=p.clone().addScaledVector(normal,3.2).addScaledVector(tangent,-5.3).addScaledVector(side,2.2),orbit=p.clone().addScaledVector(normal,8).add(new THREE.Vector3(5,3,5)),cockpit=p.clone().addScaledVector(normal,.55).addScaledVector(tangent,.65);camera.position.lerp(cameraMode===0?chase:cameraMode===1?orbit:cockpit,Math.min(1,dt*4));camera.lookAt(cameraMode===2?p.clone().addScaledVector(tangent,6):p);journeyAudio.setVehicle('flight',{active:true,speed:throttle*18,throttle});updateTelemetry();if(progress>=1){setStatus('ARRIVED');arrive();return;}}
 else if(!flying){const t=now*.00012;aircraft.position.set(Math.sin(t)*12,4,Math.cos(t)*12);aircraft.rotation.set(-lift*.12,t+Math.PI/2,bank-.12);camera.position.set(12,12,innerWidth<760?35:26);camera.lookAt(0,0,0);}
 if(!prefersReducedMotion()&&!paused){earth.rotation.y+=dt*.018;flightWater.rotation.y=earth.rotation.y;flightWater.material.uniforms.time.value=now*.001;clouds.rotation.y+=dt*.015;}renderer.render(scene,camera);
}
requestAnimationFrame(animate);
const flightCanvas=$('#flightCanvas');flightCanvas.addEventListener('webglcontextlost',event=>{event.preventDefault();contextLost=true;paused=true;setStatus('3D PAUSED');$('#flightRoute').textContent='Graphics paused. You can still enter the selected destination.';setButtons();journeyAudio.setVehicle('flight',{active:false});});flightCanvas.addEventListener('webglcontextrestored',()=>{renderer=null;try{setup();if(path)buildPath(to,currentOrigin);paused=false;setStatus(flying?'EN ROUTE':'STANDBY');setButtons();}catch{setStatus('2D MODE');}});

try{
 const old=$('#globeCanvas'),canvas=document.createElement('canvas');canvas.id='globeCanvas3D';canvas.setAttribute('aria-label','Earth with clickable city markers. Use the destination buttons for keyboard access.');old.hidden=true;old.after(canvas);const r=new THREE.WebGLRenderer({canvas,antialias:innerWidth>760,alpha:true,powerPreference:'high-performance'});r.setPixelRatio(Math.min(devicePixelRatio||1,innerWidth<760?1.2:1.65));const s=new THREE.Scene(),cam=new THREE.PerspectiveCamera(40,1,.1,100);cam.position.set(0,0,16);s.add(new THREE.HemisphereLight(0xffffff,0x254653,2.5));const light=new THREE.DirectionalLight(0xffecc8,3);light.position.set(-6,6,10);s.add(light);const group=new THREE.Group();s.add(group);const globe=new THREE.Mesh(new THREE.SphereGeometry(4.5,innerWidth<760?64:96,innerWidth<760?48:72),new THREE.MeshStandardMaterial({map:earthTexture,roughness:.52,metalness:.08}));group.add(globe);const water=tidalWater(4.61);group.add(water);const markers=[];destinations.forEach(d=>{const marker=new THREE.Mesh(new THREE.SphereGeometry(.07,10,8),new THREE.MeshBasicMaterial({color:0xf7d68d}));marker.position.copy(geo(d.lat,d.lon,4.58));marker.userData.city=d.city;group.add(marker);markers.push(marker);});let rotation=0,target=0,auto=true,drag=false,lastX=0,startX=0,lastTime=performance.now();const ray=new THREE.Raycaster();canvas.style.touchAction='pan-y';canvas.onpointerdown=e=>{drag=true;auto=false;startX=lastX=e.clientX;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){target+=(e.clientX-lastX)*.008;lastX=e.clientX;}};canvas.onpointerup=e=>{drag=false;if(Math.abs(e.clientX-startX)>8)return;const rect=canvas.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),cam);const hit=ray.intersectObjects(markers);if(hit[0]?.object.userData.city)fly(hit[0].object.userData.city);};canvas.onpointercancel=()=>drag=false;$('#globeReset').addEventListener('click',()=>auto=true);window.addEventListener('zr:destination',e=>{auto=false;target=-(e.detail.lon+90)*Math.PI/180;});
 function renderGlobe(now){requestAnimationFrame(renderGlobe);const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;const rect=canvas.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight||document.hidden)return;const ratio=r.getPixelRatio();if(canvas.width!==Math.round(rect.width*ratio)||canvas.height!==Math.round(rect.height*ratio)){r.setSize(rect.width,rect.height,false);cam.aspect=rect.width/rect.height;cam.updateProjectionMatrix();}if(auto&&!prefersReducedMotion())target+=dt*.08;rotation=THREE.MathUtils.lerp(rotation,target,.08);group.rotation.y=rotation;if(!prefersReducedMotion())water.material.uniforms.time.value=now*.001;r.render(s,cam);}requestAnimationFrame(renderGlobe);
}catch{$('#globeCanvas').hidden=false;$('#globeCanvas3D')?.remove();}
